corporate_design.toad_component_blueprint:
canvas {
  size: 880px 580px;
  fill: #F5F3EF;
  font-family: "Sora, sans-serif";
}

>lavender = #DDD6FE;
>sage = #2E4A40;

rect #mentalCard {
  at: center of canvas;
  size: 780px 480px;
  fill: #FFFFFF;
  radius: 20px;
}

text #sanctuaryHeader {
  at: top left of #mentalCard offset 40px 40px;
  content: "AETHER // RAUM FÜR DIE SEELE";
  font-size: 13px;
  font-weight: 600;
  color: >sage;
}

text #sanctuaryTitle {
  at: below #sanctuaryHeader offset 16px;
  content: "Innehalten. Durchatmen. Kraft finden.";
  font-size: 32px;
  font-weight: 400;
  color: >sage;
}
